#!/usr/bin/env python3
"""Create a locked before/after review from active records and checked sources."""
from pathlib import Path
import gzip,json,copy
root=Path(__file__).resolve().parent.parent
hist=root/'eternal/src/main/resources/data/eternalengine/eternal/history'
P='events_wikipedia.json.gz';Q='events_wikipedia_regional.json.gz'
w=lambda title,rev:f'https://en.wikipedia.org/w/index.php?title={title}&oldid={rev}'
inputs=[
 (P,'wpy_5d4804a20a',dict(name='c. 2600 BC: A study suggests wheat appears in the lower Yellow River region',start=-2600,end=-2599,lat=36.4,lon=118.4,radiusKm=200,kind='cultural',confidence='wikipedia_region'),[w('History_of_agriculture_in_China',1380774086),w('Wheat',1382280112),w('Shandong',1381551280),'https://www.nature.com/articles/s41477-018-0141-x','https://link.springer.com/article/10.1007/s00334-019-00732-7'],"The old record discussed Near Eastern grains in China but was located in the Levant at 3000 BCE. A radiocarbon and Bayesian modelling study suggests wheat reached the lower Yellow River around 2600 BCE; its timing and route remain disputed. This corrected note is specifically about wheat, not every West Asian grain or exact year. Shandong's modern province coordinate is a regional gameplay reference and not an archaeological site; not all sites or the whole river are within the search radius. The earlier general claim is preserved in the before snapshot, not asserted by the corrected row."),
 (P,'wpy_75cae27825',dict(name='c. 3000 BC: Puerto Hormiga in northern Colombia has early pottery; its dating is debated',lat=10.25861,lon=-75.34611,radiusKm=50,kind='cultural',effect='note',confidence='wikipedia_region'),[w('Puerto_Hormiga_archaeological_site',1287853123),w('Arjona,_Bol%C3%ADvar',1374693500),'https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/puerto-hormiga'],"The original point was in central Colombia, not the northern Bolivar region. Arjona town is a regional reference point near the archaeological site, not its precise coordinates. Wikipedia dates the site 4000–3100 BCE; Encyclopedia of Latin American History and Culture gives 3100–2500 BCE, so this note does not assert exact occupation in 3000 BCE. Puerto Badel is not established as a separate first settlement, and the pottery is not claimed to be the first in Colombia or the Americas."),
 (P,'wpy_d3c69e6bff',dict(name='c. 3000 BC: Naqada culture and early Egyptian writing developed over preceding centuries',radiusKm=100,kind='cultural',effect='note',confidence='wikipedia_region'),[w('Naqada_culture',1375256530),w('Egyptian_hieroglyphs',1380056832)],"The previous row combined a broad Naqada cultural span with a claim that the first hieroglyphs were at Abydos in 3500 BCE, and applied a political effect. Chronology differs within the Naqada article; the hieroglyph article dates the development of hieroglyphic writing around the 33rd century BCE. This note does not assign a precise first date or claim that the Naqada point marks the Abydos tomb. Regional marker and radius are gameplay references."),
 (P,'wpy_0155748eec',dict(name='c. 3000 BC: Newgrange is a Neolithic passage tomb; construction dating varies'),[w('Newgrange',1381331331),'https://heritageireland.ie/places-to-visit/bru-na-boinne-visitor-centre-newgrange-knowth-and-dowth/'],"Wikipedia states construction around 3100 BCE and also reports that some put it at 3000–2500 BCE; Heritage Ireland gives around 3200 BCE. The old record presented the later 3000–2500 range as the only date, while placing it in a single year. This notes differing estimates without claiming exact construction or use in 3000 BCE; coordinate and 20 km gameplay radius are retained."),
 (Q,'wpr_17d9b47607',dict(name='c. 3000 BC: Early Egyptian camel evidence is sparse; domestication origins are debated',kind='cultural'),[w('Camel',1382379831),'https://www.ucl.ac.uk/museums-static/digitalegypt/foodproduction/camel.html'],"The old row confidently said camels were domesticated in Egypt around 3000 BCE. Wikipedia says the timing is disputed and gives possible third-millennium dromedary origins in Somalia or southern Arabia; UCL notes sporadic Early Dynastic evidence in Egypt and much later regular use. Early evidence is not proof that Egypt was the place of domestication, or of an exact year. The Egyptian point and radius are regional gameplay references, not an excavation location."),
]
updates=[]
for pack,id,fields,sources,note in inputs:
 with gzip.open(hist/pack,'rt',encoding='utf8') as f:d=json.load(f)
 hits=[x for x in d['events'] if x.get('id')==id]
 if len(hits)!=1:raise ValueError('Bad source id '+id)
 before=hits[0];after=copy.deepcopy(before);after.update(fields)
 after['r2SourceEvidence']={'sources':sources,'review_note':note,'date_precision':'Approximate context/reference slot; not evidence of an exact year.','location_precision':'Regional reference, not an exact archaeological boundary.' if after['confidence']=='wikipedia_region' else 'Monument location; radius is a gameplay setting.','reviewed_as_of':'2026-10-28'}
 updates.append({'pack':pack,'event_id':id,'before':before,'after':after})
(root/'r2_wikipedia/reviews/3000_bce_existing_corrections_2026-10.json').write_text(json.dumps({'schema':'eternal-r2-3000bce-existing-v1','updates':updates},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
